@Fold.fold_step_vis
     : forall (E MN T : Type -> Type) (MT : Monad.Monad T) (handle : forall X : Type, E X -> T X)
         (sample : forall X : Type, MN X -> T X) (A X : Type) (e : E X)
         (k : X -> PTreeDefinition.ptree E MN A),
       @Fold.fold_step E MN T MT handle sample A
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.VisF E MN A (PTreeDefinition.ptree E MN A) X e k
         |} =
       @Monad.bind T MT X (PTreeDefinition.ptree E MN A + A) (handle X e)
         (fun x : X =>
          @Monad.ret T MT (PTreeDefinition.ptree E MN A + A)
            (@inl (PTreeDefinition.ptree E MN A) A (k x)))

@Fold.fold_step_prob
     : forall (E MN T : Type -> Type) (MT : Monad.Monad T) (handle : forall X : Type, E X -> T X)
         (sample : forall X : Type, MN X -> T X) (A X : Type) (mu : MN X)
         (k : X -> PTreeDefinition.ptree E MN A),
       @Fold.fold_step E MN T MT handle sample A
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.ProbF E MN A (PTreeDefinition.ptree E MN A) X mu k
         |} =
       @Monad.bind T MT X (PTreeDefinition.ptree E MN A + A) (sample X mu)
         (fun x : X =>
          @Monad.ret T MT (PTreeDefinition.ptree E MN A + A)
            (@inl (PTreeDefinition.ptree E MN A) A (k x)))

@State.get
     : forall (S : Type) (E MN : Type -> Type),
       @CategoryOps.ReSum (Type -> Type) Function.IFun (State.stateE S) E ->
       PTreeDefinition.ptree E MN S

@State.put
     : forall (S : Type) (E MN : Type -> Type),
       @CategoryOps.ReSum (Type -> Type) Function.IFun (State.stateE S) E ->
       S -> PTreeDefinition.ptree E MN unit

@State.observe_run_state
     : forall (S : Type) (E MN : Type -> Type) (A : Type)
         (t : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A)
         (s : S),
       @PTreeDefinition.observe E MN (S * A) (@State.run_state S E MN A t s) =
       match @PTreeDefinition.observe (Sum.sum1 (State.stateE S) E) MN A t with
       | @PTreeDefinition.RetF _ _ _ _ a =>
           @PTreeDefinition.RetF E MN (S * A) (PTreeDefinition.ptree E MN (S * A)) (s, a)
       | @PTreeDefinition.TauF _ _ _ _ u =>
           @PTreeDefinition.TauF E MN (S * A) (PTreeDefinition.ptree E MN (S * A))
             (@State.run_state S E MN A u s)
       | @PTreeDefinition.VisF _ _ _ _ X (@Sum.inl1 _ _ _ se) k =>
           let
           '(s', x) := @State.state_response S X se s in
            @PTreeDefinition.TauF E MN (S * A) (PTreeDefinition.ptree E MN (S * A))
              (@State.run_state S E MN A (k x) s')
       | @PTreeDefinition.VisF _ _ _ _ X (@Sum.inr1 _ _ _ fe) k =>
           @PTreeDefinition.VisF E MN (S * A) (PTreeDefinition.ptree E MN (S * A)) X fe
             (fun x : X => @State.run_state S E MN A (k x) s)
       | @PTreeDefinition.ProbF _ _ _ _ X mu k =>
           @PTreeDefinition.ProbF E MN (S * A) (PTreeDefinition.ptree E MN (S * A)) X mu
             (fun x : X => @State.run_state S E MN A (k x) s)
       end

@StateFacts.run_state_ret
     : forall (S : Type) (E MN : Type -> Type) (A : Type) (a : A) (s : S),
       @PStruct.pstruct E MN (S * A) (S * A) (@eq (S * A))
         (@State.run_state S E MN A
            {|
              PTreeDefinition._observe :=
                @PTreeDefinition.RetF (Sum.sum1 (State.stateE S) E) MN A
                  (PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A) a
            |} s)
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.RetF E MN (S * A) (PTreeDefinition.ptree E MN (S * A)) (s, a)
         |}

@StateFacts.run_state_tau
     : forall (S : Type) (E MN : Type -> Type) (A : Type)
         (t : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A)
         (s : S),
       @PStruct.pstruct E MN (S * A) (S * A) (@eq (S * A))
         (@State.run_state S E MN A
            {|
              PTreeDefinition._observe :=
                @PTreeDefinition.TauF (Sum.sum1 (State.stateE S) E) MN A
                  (PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A) t
            |} s)
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.TauF E MN (S * A) (PTreeDefinition.ptree E MN (S * A))
               (@State.run_state S E MN A t s)
         |}

@StateFacts.run_state_prob
     : forall (S : Type) (E MN : Type -> Type) (A X : Type) (mu : MN X)
         (k : X -> PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A)
         (s : S),
       @PStruct.pstruct E MN (S * A) (S * A) (@eq (S * A))
         (@State.run_state S E MN A
            {|
              PTreeDefinition._observe :=
                @PTreeDefinition.ProbF (Sum.sum1 (State.stateE S) E) MN A
                  (PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A) X mu k
            |} s)
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.ProbF E MN (S * A) (PTreeDefinition.ptree E MN (S * A)) X mu
               (fun x : X => @State.run_state S E MN A (k x) s)
         |}

@StateFacts.run_state_pstruct
     : forall (S : Type) (E MN : Type -> Type) (A B : Type) (RR : A -> B -> Prop)
         (t : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A)
         (u : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN B)
         (s : S),
       @PStruct.pstruct (Sum.sum1 (State.stateE S) E) MN A B RR t u ->
       @PStruct.pstruct E MN (S * A) (S * B) (@State.state_result_rel S A B RR)
         (@State.run_state S E MN A t s) (@State.run_state S E MN B u s)

@StateStrong.run_state_pstrong
     : forall (S : Type) (E MN : Type -> Type) (NI : Measure.SemanticMeasure MN)
         (NC : @Measure.SemanticMeasureCoreLaws MN NI) (A B : Type) (RR : A -> B -> Prop)
         (t : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A)
         (u : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN B)
         (s : S),
       @PStrong.pstrong (Sum.sum1 (State.stateE S) E) MN NI NC A B RR t u ->
       @PStrong.pstrong E MN NI NC (S * A) (S * B) (@State.state_result_rel S A B RR)
         (@State.run_state S E MN A t s) (@State.run_state S E MN B u s)

@StateFold.state_effect_get
     : forall (S : Type) (E T : Type -> Type) (MT : Monad.Monad T)
         (handle : forall X : Type, E X -> T X) (s : S),
       @StateFold.state_effect S E T MT handle S (@Sum.inl1 (State.stateE S) E S (State.Get S)) s =
       @Monad.ret T MT (S * S) (s, s)

@StateFold.state_effect_put
     : forall (S : Type) (E T : Type -> Type) (MT : Monad.Monad T)
         (handle : forall X : Type, E X -> T X) (s s' : S),
       @StateFold.state_effect S E T MT handle unit
         (@Sum.inl1 (State.stateE S) E unit (State.Put S s')) s =
       @Monad.ret T MT (S * unit) (s', tt)

@StateFold.state_effect_forward
     : forall (S : Type) (E T : Type -> Type) (MT : Monad.Monad T)
         (handle : forall X : Type, E X -> T X) (X : Type) (e : E X) (s : S),
       @StateFold.state_effect S E T MT handle X (@Sum.inr1 (State.stateE S) E X e) s =
       @Monad.bind T MT X (S * X) (handle X e) (fun x : X => @Monad.ret T MT (S * X) (s, x))

@StateFold.state_sample_preserves_state
     : forall (S : Type) (MN T : Type -> Type) (MT : Monad.Monad T)
         (sample : forall X : Type, MN X -> T X) (X : Type) (mu : MN X)
         (s : S),
       @StateFold.state_sample S MN T MT sample X mu s =
       @Monad.bind T MT X (S * X) (sample X mu) (fun x : X => @Monad.ret T MT (S * X) (s, x))

@Runner.run_sound
     : forall (MN : Type -> Type) (Seed : Type)
         (sample : forall X : Type, MN X -> Seed -> Runner.draw_result X * Seed)
         (A : Type) (fuel : nat) (t : PTreeDefinition.ptree Sum.void1 MN A)
         (seed : Seed) (result : Runner.outcome A) (seed' : Seed),
       @Runner.run MN Seed sample A fuel t seed = (result, seed') ->
       @Runner.finished A result -> @Runner.executes MN Seed sample A t seed result seed'

@Runner.run_finished_iff
     : forall (MN : Type -> Type) (Seed : Type)
         (sample : forall X : Type, MN X -> Seed -> Runner.draw_result X * Seed)
         (A : Type) (t : PTreeDefinition.ptree Sum.void1 MN A) (seed : Seed)
         (result : Runner.outcome A) (seed' : Seed),
       @Runner.executes MN Seed sample A t seed result seed' <->
       @Runner.finished A result /\
       (exists fuel : nat, @Runner.run MN Seed sample A fuel t seed = (result, seed'))

@Runner.run_finished_more_fuel
     : forall (MN : Type -> Type) (Seed : Type)
         (sample : forall X : Type, MN X -> Seed -> Runner.draw_result X * Seed)
         (A : Type) (n m : nat) (t : PTreeDefinition.ptree Sum.void1 MN A)
         (seed : Seed) (result : Runner.outcome A) (seed' : Seed),
       n <= m ->
       @Runner.run MN Seed sample A n t seed = (result, seed') ->
       @Runner.finished A result -> @Runner.run MN Seed sample A m t seed = (result, seed')

