     : forall f : bool -> rat.rat,
       @FiniteEnum.finite_expect rat.rat_rat__canonical__Num_NumDomain bool
         (fun b : bool =>
          match
            @SubEnumQ.pick_interval bool (@Representation.subenumQ_data bool StateCounter.coin)
              (SubEnumQ.quantile_value (StateCounter.bit_quantile b))
          with
          | @Some _ x => f x
          | @None _ =>
              @ssralg.GRing.zero
                (ssrnum.Num.NumDomain.Exports.Num_NumDomain__to__GRing_Nmodule
                   rat.rat_rat__canonical__Num_NumDomain)
          end) StateCounter.coin_entries =
       @FiniteEnum.finite_expect rat.rat_rat__canonical__Num_NumDomain bool f
         (@Representation.subenumQ_data bool StateCounter.coin)
